<section class="split"><div class="panel"><h2>نرخ جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>عنوان<input name="name" placeholder="مالیات بر ارزش افزوده" required></label><label>کشور (ISO دوحرفی)<input name="country" maxlength="2" placeholder="RU؛ خالی یعنی همه"></label><label>ارز<input name="currency" maxlength="8" placeholder="RUB؛ خالی یعنی همه"></label><label>درصد مالیات<input type="number" name="rate" min="0" max="100" step="0.0001" required></label><label>اولویت<input type="number" name="priority" min="0" value="100"></label><button>ذخیره نرخ</button></form></div><div class="panel"><h2>قانون تطبیق</h2><p>نرخ دقیق کشور و ارز در اولویت است. مالیات هنگام صدور فاکتور ثابت می‌شود و تغییر بعدی نرخ، فاکتورهای قبلی را تغییر نمی‌دهد.</p></div></section>
<section class="panel"><h2>نرخ‌های ثبت‌شده</h2><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>کشور</th><th>ارز</th><th>نرخ</th><th>اولویت</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($taxes as $tax):?><tr><td><?=Security::e($tax['name'])?></td><td><?=Security::e($tax['country']?:'همه')?></td><td><?=Security::e($tax['currency']?:'همه')?></td><td><?=Security::e($tax['rate'])?>٪</td><td><?=Security::e($tax['priority'])?></td><td><?=((int)$tax['is_active']===1?'فعال':'غیرفعال')?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$tax['id']?>"><button class="secondary">تغییر وضعیت</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
